var qs = $json.query || {};
var startDate = qs.start_date || new Date(Date.now() - 7 * 86400000).toISOString();
var endDate = qs.end_date || new Date().toISOString();
var workflowName = (qs.workflow_name || '').toString().trim();
var page = Math.max(1, parseInt(qs.page || '1', 10));
var pageSize = Math.min(200, Math.max(1, parseInt(qs.page_size || '50', 10)));
var offset = (page - 1) * pageSize;

var whereClause = "started_at >= '" + startDate + "'::timestamptz AND started_at <= '" + endDate + "'::timestamptz";
if (workflowName) {
  var escaped = workflowName.replace(/'/g, "''").replace(/%/g, '\\%').replace(/_/g, '\\_');
  whereClause += " AND workflow_name ILIKE '%" + escaped + "%' ESCAPE '\\'";
}

var dataQuery = "SELECT id, workflow_name, workflow_id, execution_id, channel, status, started_at, completed_at, duration_ms, tenant_id, correlation_id, error_message, created_at FROM ops.workflow_audit WHERE " + whereClause + " ORDER BY started_at DESC LIMIT " + pageSize + " OFFSET " + offset;
var countQuery = "SELECT COUNT(*) AS total FROM ops.workflow_audit WHERE " + whereClause;

return [{ json: { dataQuery: dataQuery, countQuery: countQuery, page: page, pageSize: pageSize, offset: offset } }];

